let language='de';
try { const saved=localStorage.getItem('dovit.language'); language=['de','fr'].includes(saved)?saved:(navigator.language.startsWith('fr')?'fr':'de'); } catch { language=navigator.language.startsWith('fr')?'fr':'de'; }
function t(source){
 const column=language==='fr'?1:0;
 if(messages[source])return messages[source][column];
 const patterns=[
  [/^(\d+) sichtbar$/,['$1 sichtbar','$1 affiché(s)']],
  [/^Unbekanntes Signal (\d+)$/,['Unbekanntes Signal $1','Signal inconnu $1']],
  [/^(.*) · (\d+) Meldungen$/,['$1 · $2 Meldungen','$1 · $2 messages']],
  [/^Gespeichert: (.*)\. Noch NICHT aktiv\.$/,['Gespeichert: $1. Noch NICHT aktiv.','Enregistré : $1. PAS encore actif.']],
  [/^Endpunkt (.*) ist bereits zugeordnet$/,['Endpunkt $1 ist bereits zugeordnet','Point de données $1 déjà affecté']],
  [/^(.*): nichtnegative ganze Zahl erforderlich$/,['$1: nichtnegative ganze Zahl erforderlich','$1 : entier positif ou nul obligatoire']],
  [/^(.*): endliche Zahl erforderlich$/,['$1: endliche Zahl erforderlich','$1 : nombre fini obligatoire']]
 ];
 for(const [pattern,translations] of patterns)if(pattern.test(source))return source.replace(pattern,translations[column]);
 return source;
}
function setText(element,source){element.dataset.i18n=source;element.textContent=t(source);}
function translateStatic(){
 document.documentElement.lang=language; document.title='Dovit Bridge';
 document.querySelectorAll('[data-i18n]').forEach(el=>{
  const text=Array.from(el.childNodes||(el.firstChild?[el.firstChild]:[])).find(child=>child.nodeType===Node.TEXT_NODE);
  if(text)text.nodeValue=t(el.dataset.i18n);else if(!el.children.length)el.textContent=t(el.dataset.i18n);
 });
 document.querySelectorAll('[data-i18n-placeholder]').forEach(el=>el.placeholder=t(el.dataset.i18nPlaceholder));
 document.querySelectorAll('[data-i18n-label]').forEach(el=>el.setAttribute('aria-label',t(el.dataset.i18nLabel)));
}
